package com.fuelflex.platform.reception.repository; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import com.fuelflex.platform.reception.entity.Reception; import com.fuelflex.platform.reception.model.ReceptionStatus; public interface ReceptionRepository extends JpaRepository<Reception,UUID>{ Page<Reception> findByOrganizationIdAndCreatedById(UUID organizationId,UUID userId,Pageable p); Page<Reception> findByOrganizationId(UUID organizationId,Pageable p); @EntityGraph(attributePaths={"station","purchaseOrder","createdBy","supervisorReviewedBy","items","items.product"}) Optional<Reception> findByIdAndOrganizationId(UUID id,UUID organizationId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from Reception r where r.id=:id and r.organization.id=:oid") Optional<Reception> lockByIdAndOrganizationId(@Param("id")UUID id,@Param("oid")UUID oid); long countByOrganizationIdAndStatus(UUID organizationId,ReceptionStatus status); boolean existsByPurchaseOrderIdAndStatusIn(UUID purchaseOrderId,Collection<ReceptionStatus> statuses); }
